Lemma premap_cells_frameD : forall W m m', premap_cells m -> munch W m m' ->
  disjoint_from W 0xb2108 8 -> disjoint_from W 0x149da0 8 -> disjoint_from W 0x14beb8 8 -> disjoint_from W 0x14bf00 8 ->
